<section class="grid cols-2 module-grid"><div class="card"><div class="card-heading compact"><div><span class="section-kicker">NOVA FILA</span><h2>Organizar atendimento</h2></div></div><form method="post" action="/suporte/filas" class="form-grid"><?=csrf_field()?><label>Sistema<select name="system_id" required><?php foreach($systems as $system):?><option value="<?=$system['id']?>"><?=e($system['name'])?></option><?php endforeach;?></select></label><label>Nome<input name="name" maxlength="120" required placeholder="Financeiro, tecnico, onboarding"></label><label>Categoria<input name="category" maxlength="60"></label><label>Prioridade padrao<select name="default_priority"><option value="low">Baixa</option><option value="normal" selected>Normal</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></label><label>Primeira resposta (h)<input type="number" min="1" max="720" name="first_response_hours" value="8"></label><label>Resolucao (h)<input type="number" min="1" max="2160" name="resolution_hours" value="48"></label><div class="actions span-3"><button>Criar fila</button></div></form></div><div class="card data-card"><div class="card-heading compact"><h2>Filas de atendimento</h2></div><div class="table-wrap"><table><thead><tr><th>Sistema / Fila</th><th>Categoria</th><th>SLA</th><th>Abertos</th></tr></thead><tbody><?php foreach($queues as $queue):?><tr><td><strong><?=e($queue['system_name'])?></strong><br><?=e($queue['name'])?></td><td><?=e($queue['category']?:'-')?></td><td><?=e($queue['first_response_hours'])?>h / <?=e($queue['resolution_hours'])?>h</td><td><span class="badge <?=$queue['open_tickets']?'warning':'success'?>"><?=$queue['open_tickets']?></span></td></tr><?php endforeach;?></tbody></table></div></div></section>
