cao e quando encaminhar para atendimento humano."></textarea></label><div class="actions span-3"><button>Salvar configuracao de IA</button></div></form><div class="table-wrap"><table><thead><tr><th>Aplicativo</th><th>Provedor / Modelo</th><th>RAG</th><th>Confianca</th><th>Escalonamento</th><th>Status</th></tr></thead><tbody><?php foreach($aiConfigs as $config):?><tr><td><strong><?=e($config['system_name'])?></strong></td><td><?=e($config['provider'].' / '.($config['model']?:'nao definido'))?><br><small><?=e($config['credential_env_key']?:'Sem credencial configurada')?></small></td><td><?=$config['rag_enabled']?'Sim':'Nao'?></td><td><?=number_format((float)$config['min_confidence']*100,0)?>%</td><td><?=e($config['fallback_queue_name']?:'-')?></td><td><span class="badge <?=$config['active']?'success':'warning'?>"><?=$config['active']?'Ativa':'Desativada'?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card data-card module-card"><div class="card-heading"><div><span class="section-kicker">FILA UNIFICADA</span><h2>Chamados</h2></div><form method="get" action="/suporte" class="filter-row"><select name="system_id"><option value="0">Todos os aplicativos</option><?php foreach($systems as $system):?><option value="<?=$system['id']?>" <?=$systemFilter===(int)$system['id']?'selected':''?>><?=e($system['name'])?></option><?php endforeach;?></select><select name="queue_id"><option value="0">Todas as filas</option><?php foreach($queues as $queue):?><option value="<?=$queue['id']?>" <?=$queueFilter===(int)$queue['id']?'selected':''?>><?=e($queue['system_name'].' · '.$queue['name'])?></option><?php endforeach;?></select><select name="status"><option value="">Todos os status</option><?php foreach(['open','in_progress','waiting_customer','resolved','closed'] as $value):?><option <?=$statusFilter===$value?'selected':''?>><?=$value?></option><?php endforeach;?></select><button>Filtrar</button></form></div></section>
<section class="support-board"><?php foreach($tickets as $ticket):$isLate=!empty($ticket['first_response_due_at'])&&strtotime($ticket['first_response_due_at'])<time()&&$ticket['status']==='open';?><article class="card ticket-card"><div class="ticket-head"><div><span class="section-kicker"><?=e($ticket['system_name'])?> · <?=e($ticket['queue_name']?:'Sem fila')?> · #<?=e($ticket['id'])?></span><h2><?=e($ticket['subject'])?></h2></div><span class="badge <?=$isLate?'danger':''?>"><?=e($ticket['priority'])?></span></div><p class="muted"><?=e($ticket['customer_name']?:'Cliente nao informado')?> · <?=e($ticket['customer_email'])?></p><?php if($ticket['description']):?><p><?=nl2br(e($ticket['description']))?></p><?php endif;?><div class="ticket-meta"><span>Status: <strong><?=e($ticket['status'])?></strong></span><span>Responsavel: <strong><?=e($ticket['assigned_name']?:'Nao atribuido')?></strong></span><span class="<?=$isLate?'text-danger':''?>">1a resposta: <?=e($ticket['first_response_due_at']?:'-')?></span></div><?php foreach($messagesByTicket[$ticket['id']]??[] as $message):?><div class="ticket-message <?=$message['internal_note']?'internal':''?>"><strong><?=e($message['author_name'])?><?=$message['internal_note']?' · nota interna':''?></strong><p><?=nl2br(e($message['body']))?></p></div><?php endforeach;?><form method="post" action="/suporte/atualizar" class="form-grid compact-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$ticket['id']?>"><label>Status<select name="status"><?php foreach(['open','in_progress','waiting_customer','resolved','closed'] as $value):?><option <?=$ticket['status']===$value?'selected':''?>><?=$value?></option><?php endforeach;?></select></label><label>Prioridade<select name="priority"><?php foreach(['low','normal','high','urgent'] as $value):?><option <?=$ticket['priority']===$value?'selected':''?>><?=$value?></option><?php endforeach;?></select></label><label>Fila<select name="queue_id"><option value="">Sem fila</option><?php foreach($queues as $queue):?><option value="<?=$queue['id']?>" <?=((int)$ticket['queue_id']===(int)$queue['id'])?'selected':''?>><?=e($queue['system_name'].' · '.$queue['name'])?></option><?php endforeach;?></select></label><label>Responsavel<select name="assigned_admin_user_id"><option value="">Nao atribuido</option><?php foreach($admins as $admin):?><option value="<?=$admin['id']?>" <?=((int)$ticket['assigned_admin_user_id']===(int)$admin['id'])?'selected':''?>><?=e($admin['name'])?></option><?php endforeach;?></select></label><div class="actions"><button>Atualizar</button></div></form><form method="post" action="/suporte/mensagem" class="ticket-reply"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><textarea name="body" placeholder="Registrar resposta ou diagnostico"></textarea><label class="checkbox-label"><input type="checkbox" name="internal_note" value="1"> Nota interna</label><button>Adicionar</button></form></article><?php endforeach;?><?php if(!$tickets):?><div class="card empty-state">Nenhum chamado encontrado para os filtros.</div><?php endif;?></section>
